PAGE=r'''<!doctype html><html lang=en><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><meta name=theme-color content="#070d20"><title>Spaceport · Deck</title>
<style>
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#070d20;color:#eff5ff;font-family:system-ui,sans-serif}body{background:radial-gradient(ellipse at 80% 10%,#183b5860,transparent 65%),radial-gradient(ellipse at 10% 90%,#38204c55,transparent 55%),#070d20;overflow-x:hidden}header{height:78px;display:flex;align-items:center;justify-content:space-between;padding:14px 28px;border-bottom:1px solid #273d55}.brand{letter-spacing:5px;font-size:13px;color:#80eddd}.brand b{display:block;font-size:25px;letter-spacing:1px;color:#f2f6ff}#link{font-size:11px;letter-spacing:2px;color:#89ebd4}.clock{font-size:36px;font-weight:300;line-height:1}.date{font-size:12px;color:#95aac4;text-align:right;margin-top:5px}main{padding:20px 28px 85px}.grid{display:grid;grid-template-columns:1.15fr 1fr;gap:18px}.card{border:1px solid #2b4059;border-radius:20px;padding:21px;background:#101d30bd;min-width:0}.eyebrow{font-size:10px;letter-spacing:3px;color:#79e7d6}h1,h2,p{margin:0}h2{font-size:21px;margin:9px 0 16px}.big{font-size:54px;font-weight:300;letter-spacing:-2px}.muted{color:#9bafc7}.small{font-size:13px}.row{display:flex;gap:15px;align-items:center}.grow{flex:1}.team{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-top:19px}.person{padding:15px 4px;text-align:center;border:1px solid #2b4e49;border-radius:14px;background:#112a2a}.person b{display:block;font-size:28px;color:#8cebd1}.person.busy{background:#382330;border-color:#8b4056}.person.busy b{color:#ffa9ba}.person small{font-size:10px;color:#afc2d8}.event{border-left:3px solid #75ded5;padding:8px 0 8px 13px;margin:10px 0}.event b{display:block;font-size:18px;overflow-wrap:anywhere}.event small{display:block;color:#a0b8d3;margin-top:4px}.notice{padding:17px;border-radius:15px;background:#142b43;border:1px solid #315774;margin:12px 0}.notice b{font-size:20px}.notice p{margin-top:8px;white-space:pre-wrap;color:#b8cce0;line-height:1.5}.notice.urgent{border-color:#df6689;background:#3e2033}.hidden{display:none!important}nav{position:fixed;bottom:0;left:0;right:0;display:flex;justify-content:center;gap:12px;padding:12px;background:#081121f5;border-top:1px solid #25394f}button{font:inherit;background:transparent;border:1px solid #304a64;color:#a7bfd9;border-radius:12px;padding:11px 22px;cursor:pointer;min-height:44px}button.active{background:#194340;border-color:#64dcc4;color:#afffed}.statusline{margin-top:15px;font-size:12px;color:#7e98b6}.orb{width:100px;height:100px;position:relative;flex-shrink:0}.orb:before{content:'';position:absolute;inset:24px;border-radius:50%;background:radial-gradient(circle at 30% 25%,#a2f6ff,#3fa9bf 38%,#183566 75%);box-shadow:0 0 28px #3bc8eb30}.orb:after{content:'';position:absolute;inset:20px 3px;border:2px solid #d4b178;border-radius:50%;transform:rotate(-30deg) scaleY(.42)}.sky{height:320px;display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden}.planet{width:160px;height:160px;border-radius:50%;background:radial-gradient(circle at 32% 27%,#a5edec,#36758d 35%,#172944 72%);box-shadow:-16px -8px 70px #54d9ea18,inset -25px -15px 30px #030916}.orbit{position:absolute;width:340px;height:120px;border:1px solid #7ee8de6b;border-radius:50%;transform:rotate(-25deg)}.traveller{position:absolute;top:50%;left:50%;width:10px;height:10px;background:#ffdea0;border-radius:50%;box-shadow:0 0 16px #ffe4a8;animation:orbit 20s linear infinite}@keyframes orbit{from{transform:rotate(0) translateX(160px)}to{transform:rotate(360deg) translateX(160px)}}.stars{position:absolute;inset:0;background-image:radial-gradient(1px 1px at 12% 14%,#aaa,transparent),radial-gradient(2px 2px at 78% 20%,#8af,transparent),radial-gradient(1px 1px at 18% 80%,#fff,transparent),radial-gradient(1px 1px at 88% 65%,#eee,transparent)}#alert{position:fixed;inset:0;background:#101426fa;z-index:3;padding:45px 8%;display:flex;flex-direction:column;justify-content:center;border:4px solid #e180a1}#alert h1{font-size:42px;margin:20px 0}#alert p{font-size:24px;line-height:1.5;white-space:pre-wrap}#alert button{align-self:flex-start;margin-top:25px}#alert.priority{border-color:#ff899f;background:#281324fa}progress{width:100%;height:8px;accent-color:#7fe7d4;margin-top:14px}@media(max-width:700px){header{padding:14px 18px}main{padding:18px 18px 85px}.grid{grid-template-columns:1fr}.clock{font-size:30px}.brand b{font-size:21px}nav{gap:5px}nav button{padding:10px 13px}.big{font-size:48px}}@media(prefers-reduced-motion:reduce){.traveller{animation:none}}
</style>
<header><div class=brand>SPACEPORT<b>Flight deck</b></div><span id=link>CONNECTING</span><div><div id=clock class=clock>—</div><div id=date class=date></div></div></header>
<main><section id=home class=view><div class=grid><article class=card><div class=eyebrow>PLANETARY CONDITIONS</div><div class=row><div class=grow><h2 id=condition>Connecting to your station…</h2><div id=temperature class=big>—</div></div><div class=orb></div></div><p id=rain class=muted></p><div id=forecastAge class=statusline></div></article><article class=card><div class=eyebrow>NEXT ON YOUR FLIGHT PLAN</div><div id=nextEvent></div><p id=focus class=statusline></p></article><article class=card style="grid-column:1/-1"><div class=eyebrow>COMMUNICATIONS ARRAY</div><div id=own class=statusline></div><div id=team class=team></div></article></div></section>
<section id=agenda class="view hidden"><div class=eyebrow>YOUR CALENDAR</div><h2>The next seven days</h2><div id=events></div></section>
<section id=signals class="view hidden"><div class=eyebrow>RECEIVED TRANSMISSIONS</div><h2>Notifications</h2><div id=notices></div></section>
<section id=cosmos class="view hidden"><div class=card><div class=eyebrow>QUIET ORBIT</div><div class=sky><div class=stars></div><div class=planet></div><div class=orbit></div><div class=traveller></div></div><h2 style=text-align:center>A little space to breathe</h2><p id=moon class=muted style=text-align:center></p></div></section>
</main><nav><button data-view=home class=active>Overview</button><button data-view=agenda>Calendar</button><button data-view=signals>Signals</button><button data-view=cosmos>Orbit</button></nav>
<aside id=away class=hidden style="position:fixed;inset:0;z-index:5;background:#070d20;display:flex;flex-direction:column;align-items:center;justify-content:center"><div class=orb></div><h1 style="font-size:50px;margin:20px">Away</h1><p class=muted>Your station is resting</p></aside><aside id=alert class=hidden><div class=eyebrow id=alertKind>INCOMING SIGNAL</div><h1 id=alertTitle></h1><p id=alertBody></p><button id=closeAlert>Back to deck</button></aside>
<script>
const $=id=>document.getElementById(id);let key='',data=null,received=0,lastTouch=Date.now(),page=0,seen={},shown='',shownUntil=0,dismissed={};const pages=['home','agenda','signals','cosmos'];
try{const p=new URLSearchParams(location.hash.slice(1));if(p.has('pair')){localStorage.setItem('spaceport.tablet',p.get('pair'));history.replaceState(null,'',location.pathname)}key=localStorage.getItem('spaceport.tablet')||''}catch(e){}
function text(tag,value){let n=document.createElement(tag);n.textContent=value;return n}
function show(name){page=pages.indexOf(name);document.querySelectorAll('.view').forEach(v=>v.classList.toggle('hidden',v.id!==name));document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===name))}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{lastTouch=Date.now();show(b.dataset.view)});document.addEventListener('touchstart',()=>lastTouch=Date.now(),{passive:true});document.addEventListener('click',()=>lastTouch=Date.now());
function eventNode(e){let n=document.createElement('div');n.className='event';n.append(text('b',e.title||'Busy'));const start=new Date(e.start*1000),end=new Date(e.end*1000);n.append(text('small',e.all_day?start.toLocaleDateString('en-GB',{timeZone:'Europe/London',weekday:'short',day:'numeric',month:'short'})+' · All day':start.toLocaleString('en-GB',{timeZone:'Europe/London',weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+' – '+end.toLocaleTimeString('en-GB',{timeZone:'Europe/London',hour:'2-digit',minute:'2-digit'})));return n}
function render(s){$('away').classList.toggle('hidden',!s.away);if(s.away){$('events').replaceChildren();$('nextEvent').replaceChildren();$('notices').replaceChildren();$('team').replaceChildren();$('alert').classList.add('hidden');return}const w=s.weather||{},c=w.current||{},cal=s.calendar||{};$('condition').textContent=w.available&&!w.stale?c.condition||'Weather':'Weather unavailable';$('temperature').textContent=w.available&&!w.stale?Math.round(c.temperature_c)+'°':'—';const rain=w.rain_next_hour||{};$('rain').textContent=rain.status==='dry_likely'?'Looking dry for the next hour':rain.status==='rain_likely'?'Rain expected in the next hour':'Next-hour rain forecast unavailable';$('forecastAge').textContent=w.available&&!w.stale?'Updated · '+new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}):'Waiting for fresh weather data';$('nextEvent').replaceChildren();$('events').replaceChildren();if(cal.available&&!cal.stale){const events=cal.events||[];if(events.length)$('nextEvent').append(eventNode(events[0]));else $('nextEvent').append(text('h2','Clear skies ahead'));for(const e of events)$('events').append(eventNode(e));if(!events.length)$('events').append(text('p','No appointments in the next seven days.'))}else{$('nextEvent').append(text('h2','Calendar unavailable'));$('events').append(text('p','Waiting for the calendar connection.'))}
 const f=s.focus||{};$('focus').textContent=f.available&&f.focus_phase&&f.focus_phase!=='ready'?'Focus: '+f.focus_phase+(f.focus_paused?' · paused':'')+' · '+Math.floor((f.focus_remaining||0)/60)+' min remaining':'';
 $('team').replaceChildren();for(const m of s.team||[]){let n=document.createElement('div');n.className='person'+(['busy','ringing','dialing','connected','hold'].includes(m.state)?' busy':'');n.append(text('b',m.name||'?'));let call=(m.calls||[])[0];n.append(text('small',call?(call.kind==='internal'?(call.peer_first_name||call.peer_number||'Internal'):'External'):m.state||'Unknown'));$('team').append(n)}const own=(s.own||{}).calls||[];$('own').textContent=s.connected?(own.length?'Your extension is on a call':'Your extension is available'):'Phone link offline';$('notices').replaceChildren();for(const n of s.notifications||[]){let card=document.createElement('article');card.className='notice'+(n.priority===5?' urgent':'');card.append(text('b',n.title||'Notification'),text('p',n.body||''));if(n.progress!==undefined){let bar=document.createElement('progress');bar.max=100;bar.value=n.progress;card.append(bar)}$('notices').append(card)}if(!(s.notifications||[]).length)$('notices').append(text('p','All quiet. New notifications will appear here.'));
 const incoming=own.find(c=>c.direction==='inbound'&&c.state==='ringing');const notices=(s.notifications||[]).filter(n=>!dismissed[n.id]);const urgent=notices.find(n=>n.priority===5);const fresh=notices.find(n=>!seen[n.id]);const held=notices.find(n=>n.id===shown&&shownUntil>Date.now());let alert=incoming&&incoming.priority?{id:incoming.id,title:incoming.peer_name||incoming.peer_number||'Incoming call',body:incoming.queue_name||incoming.ring_group_name||'Priority call',priority:5,call:true}:urgent||held||fresh;
 if(alert){if(shown!==alert.id)shownUntil=Date.now()+12000;shown=alert.id;$('alertKind').textContent=alert.call?'PRIORITY CALL':alert.priority===5?'URGENT TRANSMISSION':'INCOMING SIGNAL';$('alertTitle').textContent=alert.title||'Notification';$('alertBody').textContent=alert.body||'';$('alert').classList.remove('hidden');$('alert').classList.toggle('priority',alert.priority===5);seen[alert.id]=Date.now();if(alert.priority!==5&&!alert.call)setTimeout(()=>{if(shown===alert.id){$('alert').classList.add('hidden');shown=''}},12000)}else if(shown){$('alert').classList.add('hidden');shown=''}
}
$('closeAlert').onclick=()=>{if(shown)dismissed[shown]=true;shown='';$('alert').classList.add('hidden');lastTouch=Date.now()};
async function poll(){if(!key){$('link').textContent='SETUP NEEDED';$('condition').textContent='Waiting for device setup';return}try{let r=await fetch('/tablet/api/state',{headers:{Authorization:'Bearer '+key},cache:'no-store'});if(!r.ok)throw Error();data=await r.json();received=Date.now();$('link').textContent='STATION ONLINE';render(data)}catch(e){$('link').textContent='RECONNECTING';if(Date.now()-received>30000){$('condition').textContent='Station connection lost';$('temperature').textContent='—';$('rain').textContent='Waiting for live data';$('nextEvent').replaceChildren(text('h2','Calendar unavailable'));$('events').replaceChildren();$('team').replaceChildren();$('own').textContent='Phone link unavailable'}}}
setInterval(poll,3000);poll();setInterval(()=>{const now=new Date();$('clock').textContent=now.toLocaleTimeString('en-GB',{timeZone:'Europe/London',hour:'2-digit',minute:'2-digit'});$('date').textContent=now.toLocaleDateString('en-GB',{timeZone:'Europe/London',weekday:'long',day:'numeric',month:'long'});let phase=((Date.now()/1000-947182440)/2551442.88)%1;if(phase<0)phase++;$('moon').textContent='Moon · '+Math.round((1-Math.cos(phase*Math.PI*2))*50)+'% illuminated';if(Date.now()-lastTouch>45000&&$('alert').classList.contains('hidden')){show(pages[(page+1)%pages.length]);lastTouch=Date.now()-25000}},1000);
</script></html>'''
